import test from 'node:test';
import assert from 'node:assert/strict';
import {sessionOverview,hasNoRecordedRounds} from '../../reda-2/session-overview-model.mjs';
const exercise=(id,sets=2,side='simultaneous')=>({id,name:id,dose:{sets,reps:8},side});
const mark=(id,roundsDone=0,status='pending',feedback=null)=>({exerciseId:id,roundsDone,status,feedback});
const session=progress=>({id:'test-session',progress,completedAt:null});
test('untouched prescription is not completed training',()=>{const v=sessionOverview([exercise('a')],session([mark('a')]));assert.equal(v.done,0);assert.equal(v.total,2);assert.equal(v.untouched,1);assert.equal(v.allCompleted,false);assert.equal(v.canFinish,true)});
test('both sides follow existing interleaved left/right round order',()=>{const v=sessionOverview([exercise('a',3,'both')],session([mark('a',3,'partial')]));assert.equal(v.done,3);assert.equal(v.total,6);assert.equal(v.items[0].sides,'Vänster 2 av 3 · Höger 1 av 3')});
test('partial, skipped and unregistered remain distinct',()=>{const v=sessionOverview([exercise('a'),exercise('b'),exercise('c')],session([mark('a',1,'partial'),mark('b',1,'skipped','heavy'),mark('c')]));assert.deepEqual(v.items.map(x=>x.status),['partial','skipped','pending']);assert.equal(v.done,2);assert.equal(v.remaining,4);assert.equal(v.items[1].feedback,'För tungt')});
test('all completed requires exact dose and explicit completion for every exercise',()=>{const xs=[exercise('a'),exercise('b',1,'left')];assert.equal(sessionOverview(xs,session([mark('a',2,'completed'),mark('b',1,'completed')])).allCompleted,true);assert.equal(sessionOverview(xs,session([mark('a',2,'partial'),mark('b',1,'completed')])).allCompleted,false)});
test('closed sessions cannot be ended again',()=>{const v=sessionOverview([exercise('a')],{...session([mark('a',2,'completed')]),completedAt:'2026-09-18T10:00:00Z'});assert.equal(v.canFinish,false)});
test('foreign, reordered and missing exercise identities fail closed',()=>{for(const rows of [[mark('b')],[mark('b'),mark('a')],[mark('a')]])assert.equal(sessionOverview([exercise('a'),exercise('b')],session(rows)).valid,false)});
test('duplicate prescription identities fail closed',()=>assert.equal(sessionOverview([exercise('a'),exercise('a')],session([mark('a'),mark('a')])).valid,false));
test('invalid counts and inconsistent completion fail closed',()=>{for(const p of [mark('a',-1,'partial'),mark('a',3,'completed'),mark('a',.5,'partial'),mark('a','2','completed'),mark('a',1,'completed'),mark('a',1,'pending'),mark('a',NaN,'partial')])assert.equal(sessionOverview([exercise('a')],session([p])).canFinish,false)});
test('empty and invalid prescriptions do not enable finishing',()=>{for(const xs of [null,[],[exercise('a',-1)],[exercise('a',.5)]])assert.equal(sessionOverview(xs,session([mark('a')])).canFinish,false)});
test('opening an overview never mutates prescription or progress',()=>{const xs=[exercise('a',2,'both')],s=session([mark('a',1,'partial')]),before=JSON.stringify([xs,s]);Object.freeze(xs[0].dose);Object.freeze(xs[0]);Object.freeze(xs);Object.freeze(s.progress[0]);Object.freeze(s.progress);Object.freeze(s);sessionOverview(xs,s);assert.equal(JSON.stringify([xs,s]),before)});
test('single-sided and simultaneous exercises do not double the dose',()=>{for(const side of ['left','right','simultaneous'])assert.equal(sessionOverview([exercise('a',2,side)],session([mark('a',1,'partial')])).total,2)});
test('unrecognized feedback is not interpreted as a clinical answer',()=>assert.equal(sessionOverview([exercise('a')],session([mark('a',0,'pending','better')])).items[0].feedback,''));

test('missing round counts never imply no training was recorded',()=>{assert.equal(hasNoRecordedRounds([]),false);assert.equal(hasNoRecordedRounds([{}]),false);assert.equal(hasNoRecordedRounds([{roundsDone:null}]),false);assert.equal(hasNoRecordedRounds([{roundsDone:0}]),true)});
test('history distinguishes a closed session with no recorded rounds',async()=>{const {patientHistory}=await import('../../reda-2/patient-history.mjs');const rows=patientHistory([{id:'end:s',plan_id:'p',plan_version:1,title:'Pass delvis genomfört',occurred_at:'2026-09-18T10:00:00Z'}],{sessions:[{id:'s',plan_id:'p',plan_version:1,status:'partial',completed_at:'2026-09-18T10:00:00Z',payload:{exercises:[{status:'pending',roundsDone:0}]}}]});assert.equal(rows[0].title,'Avslutat utan registrerade omgångar')});
